"""Writes tools/stats/cases_mv.txt: distances and hierarchical clustering."""
import os
here = os.path.dirname(os.path.abspath(__file__))
L = ["# generated by make_mv_cases.py"]
METRICS = ["euclidean", "squaredeuclidean", "seuclidean", "cityblock", "chebychev", "mahalanobis", "cosine", "correlation", "spearman", "hamming", "jaccard", "minkowski"]
for m in METRICS:
    L.append(f"r = pdist(A,'{m}');")
    L.append(f"r = pdist(N(:,[2 4]),'{m}');")
    L.append(f"r = pdist(round(A),'{m}');")
L += ["r = pdist(A);", "r = pdist(A,'eu');", "r = pdist(A,'Euc');", "r = pdist(A,'se');", "r = pdist(A,'seuclidean',[1 2 3 4 5]);", "r = pdist(A,'seuclidean',[1 2 0 4 5]);",
      "r = pdist(A,'minkowski',1);", "r = pdist(A,'minkowski',3);", "r = pdist(A,'minkowski',0.5);", "r = pdist(A,'minkowski',Inf);", "r = pdist(A,'minkowski',-1);",
      "r = pdist(A(:,1:3),'mahalanobis',[2 0 0;0 1 0;0 0 3]);", "r = pdist(A(:,1:3),'mahalanobis',eye(2));",
      "r = pdist(A(:,1:3),'mahalanobis',[1 2 3;2 1 4;3 4 1]);", "r = pdist(A,@(xi,xj) sum(abs(xi-xj),2));", "r = pdist(A,@(xi,xj) max(abs(xi-xj),[],2));",
      "r = pdist(A(:,1),'euclidean');", "r = pdist(A(1,:));", "r = pdist(zeros(0,3));", "r = pdist(single(A));", "r = pdist(single(A),'cityblock');", "r = pdist(A,'foo');", "r = pdist(A,'c');",
      "r = pdist(A,'co');", "r = pdist(1+2i);", "r = pdist(cat(3,A,A));", "r = pdist([1 2;1 2;1 2],'correlation');", "r = pdist([1 0 0;0 0 0;1 1 0],'cosine');", "r = pdist([1 0 0;0 0 0;1 1 0],'jaccard');",
      "r = pdist(int8([1 2;3 4;5 7]));", "r = pdist(logical([1 0 1;0 0 1;1 1 1]),'hamming');", "r = pdist(logical([1 0 1;0 0 1;1 1 1]),'jaccard');"]
# squareform
L += ["r = squareform(1:6);", "r = squareform((1:6)');", "r = squareform(squareform(1:6));", "r = squareform(pdist(A));", "r = squareform([0 1 2;1 0 3;2 3 0]);", "r = squareform(1);", "r = squareform([]);", "r = squareform(zeros(1,0));",
      "r = squareform(1:6,'tomatrix');", "r = squareform(squareform(1:6),'tovector');", "r = squareform(1:5);", "r = squareform([1 2;3 4]);", "r = squareform(ones(2,3));", "r = squareform(1:6,'foo');",
      "r = squareform(single(1:3));", "r = squareform(logical([1 0 1]));", "r = squareform('abc');", "r = squareform(1:6,'tovector');", "r = squareform(0);", "r = squareform(zeros(2));", "r = squareform([0 1;1 0],'tomatrix');",
      "r = squareform(squareform(1:3),'tomatrix');", "r = squareform(cat(3,1:3,1:3));", "r = squareform(int8(1:3));"]
# pdist2
P2 = "P(1:3,:)"
for m in ["euclidean", "squaredeuclidean", "seuclidean", "cityblock", "chebychev", "mahalanobis", "cosine", "correlation", "spearman", "hamming", "jaccard"]:
    L.append(f"r = pdist2(A,{P2},'{m}');")
L += ["r = pdist2(A,P(1:3,:));", "r = pdist2(A,A);", "r = pdist2(A(1,:),A);", "r = pdist2(A,P(1:3,1:4));", "r = pdist2(A,P(1:3,:),'minkowski',3);", "r = pdist2(A,P(1:3,:),'minkowski',Inf);",
      "r = pdist2(A,P(1:3,:),'seuclidean',[1 2 3 4 5]);", "r = pdist2(A,P(1:3,:),'mahalanobis',eye(5));", "r = pdist2(A,P(1:3,:),@(x,Z) sum(abs(x-Z),2));",
      "[d,i] = pdist2(A,P(1:3,:),'euclidean','Smallest',2); r = {d,i};", "[d,i] = pdist2(A,P(1:3,:),'euclidean','Largest',2); r = {d,i};", "[d,i] = pdist2(A,P(1:3,:),'cityblock','Smallest',1); r = {d,i};",
      "[d,i] = pdist2(A,P(1:3,:),'euclidean','Smallest',5); r = {d,i};", "[d,i] = pdist2(A,P(1:3,:),'euclidean','Smallest',[1 2]); r = {d,i};", "r = pdist2(A,P(1:3,:),'euclidean','Smallest',0);",
      "r = pdist2(single(A),P(1:3,:));", "r = pdist2(N,P(1:3,:));", "r = pdist2(A,P(1:3,:),'foo');", "r = pdist2(A);", "r = pdist2(A,P(1:3,:),'euclidean','Foo',1);", "r = pdist2(zeros(0,5),P(1:3,:));",
      "[d,i] = pdist2(A,P(1:3,:),'cityblock','Largest',2); r = {d,i};"]
# mahal
L += ["r = mahal(A(1:3,:),P);", "r = mahal(P,P);", "r = mahal(A(1:2,:),[A;P]);", "r = mahal(A,A(1:3,:));", "r = mahal(A(:,1:3),P);", "r = mahal(single(A),single(P));", "r = mahal(A(1,:),[A;P]);", "r = mahal(1,[1;2;4]);"]
# linkage
for m in ["single", "complete", "average", "weighted", "centroid", "median", "ward"]:
    L += [f"r = linkage(pdist(A),'{m}');", f"r = linkage(A,'{m}');", f"r = linkage(pdist(round(A)),'{m}');", f"r = linkage(pdist(P(1:4,:)),'{m}');"]
    L += [f"r = linkage(pdist(x(1:12)'),'{m}');"]
L += ["r = linkage(pdist(A));", "r = linkage(pdist(A),'foo');", "r = linkage(1:3,'single');", "r = linkage(1:2,'single');", "r = linkage(pdist(A),'si');", "r = linkage(pdist(A),'wa');",
      "r = linkage(A,'average','cityblock');", "r = linkage(A,'average','cosine');", "r = linkage(A,'ward','euclidean');", "r = linkage(A,'single','minkowski',3);", "r = linkage(pdist(A),'centroid');",
      "r = linkage(single(pdist(A)),'single');", "r = linkage(A,'ward','cityblock');", "r = linkage(pdist(A),'single',[]);",
      "r = linkage(zeros(1,3),'single');", "r = linkage([1 1 1],'average');", "r = linkage([2 2 2 2 2 2],'complete');", "r = linkage([1 1 1 1 1 1],'single');"]
Z = "linkage(pdist(A),'average')"
Z2 = "linkage(pdist(x(1:12)'),'complete')"
L += [f"Zl = {Z}; r = cluster(Zl,'MaxClust',2);", f"Zl = {Z}; r = cluster(Zl,'MaxClust',3);", f"Zl = {Z}; r = cluster(Zl,'MaxClust',6);", f"Zl = {Z}; r = cluster(Zl,'MaxClust',1);",
      f"Zl = {Z}; r = cluster(Zl,'MaxClust',[2 3 4]);", f"Zl = {Z}; r = cluster(Zl,'Cutoff',3);", f"Zl = {Z}; r = cluster(Zl,'Cutoff',3,'Criterion','distance');", f"Zl = {Z}; r = cluster(Zl,'Cutoff',1,'Criterion','inconsistent');",
      f"Zl = {Z}; r = cluster(Zl,'Cutoff',1.1,'Criterion','inconsistent','Depth',3);", f"Zl = {Z}; r = cluster(Zl,'Cutoff',[2 3 4]);", f"Zl = {Z}; r = cluster(Zl,'Cutoff',0);",
      f"Zl = {Z}; r = cluster(Zl,'Cutoff',100);", f"Zl = {Z}; r = cluster(Zl,'MaxClust',0);", f"Zl = {Z}; r = cluster(Zl,'MaxClust',7);", f"Zl = {Z}; r = cluster(Zl);", f"Zl = {Z}; r = cluster(Zl,'Foo',1);",
      f"Zl = {Z2}; r = cluster(Zl,'MaxClust',4);", f"Zl = {Z2}; r = cluster(Zl,'MaxClust',3);", f"Zl = {Z2}; r = cluster(Zl,'Cutoff',1);", "r = cluster([1 2 3],'MaxClust',2);",
      "r = clusterdata(A,'maxclust',3);", "r = clusterdata(A,'cutoff',1.1);", "r = clusterdata(A,'linkage','ward','maxclust',2);", "r = clusterdata(A,'distance','cityblock','linkage','single','maxclust',3);",
      f"Zl = {Z}; r = cophenet(Zl,pdist(A));", f"Zl = {Z}; [c,d] = cophenet(Zl,pdist(A)); r = {{c,d}};", f"Zl = {Z2}; [c,d] = cophenet(Zl,pdist(x(1:12)')); r = {{c,d}};",
      f"Zl = {Z}; r = cophenet(Zl,1:15);", f"Zl = {Z}; r = cophenet(Zl,1:14);", "Zl = linkage(pdist(A),'ward'); r = cophenet(Zl,pdist(A));", "r = cophenet([1 2 3],1:3);",
      f"Zl = {Z}; r = inconsistent(Zl);", f"Zl = {Z}; r = inconsistent(Zl,2);", f"Zl = {Z}; r = inconsistent(Zl,1);", f"Zl = {Z}; r = inconsistent(Zl,5);", f"Zl = {Z2}; r = inconsistent(Zl);", f"Zl = {Z}; r = inconsistent(Zl,0);",
      f"Zl = {Z}; r = inconsistent(Zl,1.5);", "r = inconsistent([1 2 3;4 5 6]);", "r = inconsistent([1 2]);"]
with open(os.path.join(here, "cases_mv.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
